// Genuine Edge requests through the isolated gateway, Auth provider and PostgreSQL.
// The session file is generated by the local GoTrue fixture and kept outside the repo.
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {readFile} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';

const gateway=process.env.SOLAR_FIXTURE_GATEWAY||'http://127.0.0.1:3200';
const db=process.env.SOLAR_FIXTURE_DB||'solar_v4114_wizard_browser';
assert.equal(new URL(gateway).hostname,'127.0.0.1');assert.equal(db,'solar_v4114_wizard_browser');
const session=JSON.parse(await readFile(process.env.SOLAR_ADMIN_FIXTURE_SESSION||'/workspace/solar-review/v4114/wizard-edge/admin-session.json','utf8'));
const admin=session.access_token,adminId=session.user.id;
const sql=query=>execFileSync('python',['/workspace/solar-review/v359/db.py',db],{input:query,encoding:'utf8'}).trim();
async function post(path,body,token){
 if(process.env.SOLAR_TRACE_IDENTITY)console.log('start',path.split('/').at(-1),body.action||'login');
 const response=await fetch(gateway+path,{method:'POST',headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{})},body:JSON.stringify(body)});
 const data=await response.json();if(process.env.SOLAR_TRACE_IDENTITY)console.log('finish',body.action||'login',response.status);
 return {status:response.status,body:data};
}
const edge=(body,token=admin)=>post('/functions/v1/solar-admin-users',body,token);
const login=(username,password)=>post('/functions/v1/solar-login',{login:username,password});
const okay=result=>{assert.equal(result.status,200,result.body.error||'request failed');assert.equal(result.body.ok,true);return result.body;};
const refused=result=>{assert.ok(result.status>=400&&result.status<500,'expected a refusal: '+result.status);assert.equal(result.body.ok,false);};
async function current(uid){return okay(await edge({action:'directory'})).users.find(row=>row.id===uid);}
const tag=randomUUID().replaceAll('-','').slice(0,12);
const username='edgeqa_'+tag,renamed=username+'_r',password=randomUUID(),nextPassword=randomUUID();
const uid=randomUUID();
const details={action:'save_details',request_id:uid,username,display_name:'موظف تجريبي '+tag,phone:'07701234987',honorific:'المهندس',password};
const sqlCount=(table,condition)=>Number(sql('select count(*) from '+table+' where '+condition));
const finalize=(user,patch={})=>({action:'finalize',request_id:randomUUID(),user_id:user.id,token:user.token,
 role:'user',active:true,permissions:{warranty:true},warehouse:user.warehouse,...patch});

// Read provider principal/trusted data without ever copying a bearer token into artifacts.
async function principal(access){
 const r=await fetch(gateway+'/auth/v1/user',{headers:{authorization:'Bearer '+access}});
 assert.ok(r.ok);return (await r.json()).id;
}
function requestCount(id){return sqlCount('solar_private.staff_admin_requests',"request_id='"+id+"'");}
const initial=await current(adminId);assert.equal(initial.active,true);assert.equal(initial.is_admin,true);
refused(await edge({action:'directory'},'unauthenticated'));

// The write reaches the handler, while the caller never receives its acknowledgement.
async function loseAcknowledgement(){
 const committed=await edge(details);assert.equal(committed.status,200,committed.body.error);
 throw new Error('synthetic connection loss after commit');
}
await assert.rejects(loseAcknowledgement,/after commit/);
assert.equal(requestCount(uid),1);
assert.equal(sqlCount('auth.users',"id='"+uid+"'"),1);
const retry=okay(await edge(details)).user;
assert.equal(retry.id,uid);assert.equal(retry.active,false);
 // The existing private-scope trigger sets ownership defaults even on inactive profiles.
 const scopeKeys=new Set(['ownSales','ownProfit','ownPayments','ownCustomers']);
 assert.ok(Object.entries(retry.permissions).every(([name,enabled])=>enabled!==true||scopeKeys.has(name)));
 for(const page of ['sale','purchase','cash','profit','system','warehouse','warranty','userActivity'])assert.notEqual(retry.permissions[page],true);
assert.equal(requestCount(uid),1);assert.equal(sqlCount('public.profiles',"username='"+username+"'"),1);
assert.equal(retry.warehouse.all,false);assert.deepEqual(retry.warehouse.ids,[]);
refused(await login(username,password));
const actorAtStageOne=await current(uid);
assert.equal(actorAtStageOne.token,retry.token);
const warehouse=okay(await edge({action:'directory'})).warehouses.find(w=>w.active&&w.isPrimary);
assert.ok(warehouse?.id);
const selected={all:false,ids:[warehouse.id],transferDirections:{fromPrimary:false,toPrimary:false,other:false}};
const saved=okay(await edge(finalize(actorAtStageOne,{warehouse:selected}))).user;
assert.equal(saved.active,true);assert.equal(saved.permissions.warranty,true);
assert.deepEqual(saved.warehouse,selected);
const firstLogin=okay(await login(username,password));
assert.equal(await principal(firstLogin.access_token),uid);
refused(await edge({action:'directory'},firstLogin.access_token));
refused(await edge({...details,request_id:randomUUID(),username:renamed},firstLogin.access_token));
assert.equal(sqlCount('public.profiles',"username='"+renamed+"'"),0);
const update={action:'save_details',request_id:randomUUID(),user_id:uid,token:saved.token,username:renamed,display_name:'موظف معدّل '+tag,honorific:'الأستاذ',phone:'07709871234'};
const updated=okay(await edge(update)).user;
assert.equal(updated.username,renamed);assert.equal(updated.display_name,update.display_name);assert.equal(updated.active,true);
assert.deepEqual(updated.permissions,saved.permissions);assert.deepEqual(updated.warehouse,saved.warehouse);
refused(await login(username,password));assert.equal(await principal(okay(await login(renamed,password)).access_token),uid);
const originalEmail=sql("select email from auth.users where id='"+uid+"'");
assert.equal(originalEmail,username+'@solar-user.local');
assert.equal(await principal(okay(await login(originalEmail,password)).access_token),uid);
const resumed=await current(uid);assert.equal(resumed.token,updated.token);
// Both old editors could append an autofilled password to unrelated profile changes.
for(const action of ['save_details','update']){
 refused(await edge({...update,action,request_id:randomUUID(),token:resumed.token,phone:'07701111000',password:nextPassword,role:'user'}));
 assert.equal((await current(uid)).token,resumed.token);
}
assert.equal(await principal(okay(await login(renamed,password)).access_token),uid);
refused(await edge(finalize(saved,{active:false})));
assert.equal((await current(uid)).active,true);
const rekey={...update,request_id:randomUUID(),token:resumed.token,changePassword:true,password:nextPassword};
const pwdResult=okay(await edge(rekey)).user;
refused(await login(renamed,password));
assert.equal(await principal(okay(await login(renamed,nextPassword)).access_token),uid);
const serialized=sql("select coalesce(string_agg(payload::text,' '),'') from solar_private.staff_admin_requests where target_id='"+uid+"'");
assert.ok(!serialized.includes(password)&&!serialized.includes(nextPassword));
for(const body of [finalize(initial,{active:false,role:'admin'}),finalize(initial,{role:'user'}),{action:'remove',request_id:randomUUID(),user_id:adminId,token:initial.token}])refused(await edge(body));
assert.equal((await current(adminId)).active,true);assert.equal((await current(adminId)).is_admin,true);

// A transaction gives the profile historical ownership that must survive archival.
const invoice=-(1+parseInt(tag.slice(0,10),16));
sql("insert into transactions(id,kind,party_name,total,cash,created_by,cashbox_user_id,notes) values("+invoice+",'sale','عميل الاختبار',15000,false,'"+uid+"','"+uid+"','edgeqa archive')");
const ledgerBefore=sql("select to_jsonb(t)::text from transactions t where t.id="+invoice);
const remove={action:'remove',request_id:randomUUID(),user_id:uid,token:pwdResult.token};
assert.equal(okay(await edge(remove)).mode,'archived');
assert.equal((await current(uid)).active,false);assert.equal(sqlCount('auth.users',"id='"+uid+"'"),1);
assert.equal(ledgerBefore,sql("select to_jsonb(t)::text from transactions t where t.id="+invoice));
assert.equal(okay(await edge(remove)).mode,'archived');assert.equal(requestCount(remove.request_id),1);
refused(await login(renamed,nextPassword));
const disposableId=randomUUID(),cleanCreate={...details,request_id:disposableId,username:username+'_d'},clean=okay(await edge(cleanCreate)).user;
const enabledClean=okay(await edge(finalize(clean))).user;
const removeClean={action:'remove',request_id:randomUUID(),user_id:clean.id,token:enabledClean.token};
assert.equal(okay(await edge(removeClean)).mode,'deleted');
assert.equal(sqlCount('auth.users',"id='"+clean.id+"'"),0);
assert.equal(await current(clean.id),undefined);
assert.equal(okay(await edge(removeClean)).mode,'deleted');
refused(await edge(cleanCreate));
assert.equal(sqlCount('auth.users',"id='"+clean.id+"'"),0);
assert.equal(await current(clean.id),undefined);
// A permanent provider record can exist even when the first independent SQL write fails.
const interruptedId=randomUUID(),pendingUsername=username+'_p',fault='qa_staff_'+tag;
const interrupted={...details,request_id:interruptedId,username:pendingUsername};
sql("create function solar_private."+fault+"() returns trigger language plpgsql as $$begin if new.action='save_details' and new.request_id='"+interruptedId+"' then raise exception 'local test interruption';end if;return new;end;$$; create trigger "+fault+" before insert on solar_private.staff_admin_requests for each row execute function solar_private."+fault+"()");
try{
 const failed=await edge(interrupted);refused(failed);assert.match(failed.body.error,/local test interruption/);
 assert.equal(sql("select active from profiles where id='"+interruptedId+"'"),'f');
 assert.equal(sql("select banned_until>now() from auth.users where id='"+interruptedId+"'"),'t');
 refused(await login(pendingUsername+'@solar-user.local',password));
}finally{sql("drop trigger "+fault+" on solar_private.staff_admin_requests;drop function solar_private."+fault+"()");}
const partial=await current(interruptedId);assert.equal(partial.active,false);
assert.equal(partial.warehouse.all,false);assert.deepEqual(partial.warehouse.ids,[]);
// A second signed-in admin session reviews the draft while the first browser is offline.
const adminLoginFile=process.env.SOLAR_ADMIN_FIXTURE_LOGIN||'/workspace/solar-review/v4114/wizard-edge/local-admin-login.json';
const adminLogin=JSON.parse(await readFile(adminLoginFile,'utf8'));
const secondAdmin=okay(await login(adminLogin.email,adminLogin.password)).access_token;
assert.equal(await principal(secondAdmin),adminId);
assert.notEqual(secondAdmin,admin);
const resumePayload={...interrupted,request_id:randomUUID(),user_id:partial.id,token:partial.token,password:undefined};
const repaired=okay(await edge(resumePayload,secondAdmin)).user;
assert.equal(repaired.id,interruptedId);assert.equal(repaired.active,false);
const reviewed=okay(await edge(finalize(repaired,{warehouse:selected}),secondAdmin)).user;
assert.equal(reviewed.active,true);assert.equal(reviewed.permissions.warranty,true);
const staleCreation=await edge(interrupted);
assert.equal(staleCreation.status,409);refused(staleCreation);
const afterRetry=await current(interruptedId);
assert.equal(afterRetry.token,reviewed.token);
assert.deepEqual(afterRetry.permissions,reviewed.permissions);
assert.deepEqual(afterRetry.warehouse,selected);
assert.equal(await principal(okay(await login(pendingUsername,password)).access_token),interruptedId);
console.log('PASS identity lifecycle via Edge + GoTrue + PostgREST: staged creation/retry, activation, username and preserved email, password change, stale updates, admin safeguards, archive/history and removal.');
